def add(n,t,ans,steps,final,hint,why,fig='',labels=None,options=None,calc=True,unordered=False,old=False):
 q=h.make('1.'+str(n),'funktioner','Tolka och jämföra funktioner',3,t,ans,steps,final,hint,fig=fig,labels=labels,options=options,skills=['begrepp','problemlösning']);q.update(poang='0/2/0',miniräknare=calc)
 if not options:q.update(svarFormat=['uttryck']*len(ans) if labels else 'uttryck',svarstyp='flera_delar' if labels else 'uttryck',tolerans=[None]*len(ans) if labels else None)
 if unordered:q['svarsstruktur']='mängd'
 (REVISED if old else TASKS).append(q);REVIEW[q['id']]={'status':'Åtgärdad: självrättning aktiverad, tydligare svarsfält och facit.' if old else 'Ny, granskad – inget fel.','C-motivering':why,'figur':'Relevant figur eller tabell.' if fig else 'Algebra eller begrepp; ingen extra illustration behövs.','verktyg':'Miniräknare tillåten, GeoGebra behövs inte.' if calc else 'Ett begreppsligt resonemang prövas utan räknare.','kommentar':final}
def axes(fig,xlim,ylim):
 X=65+370*(0-xlim[0])/(xlim[1]-xlim[0]);Y=250-200*(0-ylim[0])/(ylim[1]-ylim[0]);return fig.replace('M65 45V250H445',f'M{X} 45V250 M65 {Y}H445')
def two_colors(fig,legend):
 matches=list(re.finditer(r'<polyline[^>]+/>',fig));v=matches[-1];fig=fig[:v.start()]+v.group().replace('#096c9a','#a15320')+fig[v.end():]
 return fig.replace('0 0 500 320','0 0 500 350').replace('height="320"','height="350"').replace('</svg>',h.text(250,333,legend,16)+'</svg>')

